-- ===========================================================================
-- Part 2 — database-enforced invariants
-- ===========================================================================

-- ScanPlan: U-1 deadline (non-null iff RESOLVED, 0 < ms <= ceiling) and kind/subject consistency.
ALTER TABLE "ScanPlan"
  ADD CONSTRAINT "ScanPlan_deadline_chk" CHECK (
    ("state" = 'RESOLVED' AND "deadlineMs" IS NOT NULL AND "deadlineMs" > 0 AND "deadlineMs" <= 21600000)
    OR ("state" = 'REFUSED' AND "deadlineMs" IS NULL)),
  ADD CONSTRAINT "ScanPlan_subject_chk" CHECK (
    ("kind" = 'INITIAL' AND "scanId" IS NOT NULL AND "reverifyIssueId" IS NULL)
    OR ("kind" = 'REVERIFY' AND "reverifyIssueId" IS NOT NULL AND "scanId" IS NULL));
-- FR-011: a scan has exactly one initial plan.
CREATE UNIQUE INDEX "ScanPlan_one_initial_per_scan" ON "ScanPlan"("scanId") WHERE "kind" = 'INITIAL';

-- ExecutionUnit shape invariants.
ALTER TABLE "ExecutionUnit"
  ADD CONSTRAINT "ExecutionUnit_positive_chk" CHECK ("attempt" >= 1 AND "timeoutPolicyMs" > 0 AND "costMicros" >= 0),
  ADD CONSTRAINT "ExecutionUnit_checkpoint_chk" CHECK (
    "requiresSafetyCheckpoint" = ("executionUnitClass" IN ('BROWSER','CRAWLER','SOURCE_EXECUTION','ACTIVE_SECURITY','AUTHENTICATED_WORKFLOW','LOAD_CAPACITY'))),
  ADD CONSTRAINT "ExecutionUnit_passive_grant_chk" CHECK (
    "executionUnitClass" NOT IN ('PASSIVE_HTTP','SOURCE_STATIC','TELEMETRY') OR "targetAuthorizationId" IS NULL),
  ADD CONSTRAINT "ExecutionUnit_failure_class_chk" CHECK (
    ("status" = 'FAILED') = ("failureClass" IS NOT NULL) AND "failureClass" IS DISTINCT FROM 'DETERMINISTIC_FINDING'),
  ADD CONSTRAINT "ExecutionUnit_blocked_by_chk" CHECK (("status" = 'BLOCKED') = ("blockedByExecutionUnitId" IS NOT NULL)),
  ADD CONSTRAINT "ExecutionUnit_skipped_chk" CHECK (("status" = 'SKIPPED') = ("skippedReason" IS NOT NULL));

ALTER TABLE "ExecutionDependency"
  ADD CONSTRAINT "ExecutionDependency_no_self_chk" CHECK ("executionUnitId" <> "dependsOnExecutionUnitId");

-- Guarded transition table + frozen columns (FR-014; execution-unit-contract). Terminal rows never change.
CREATE FUNCTION public.fahes_unit_guard() RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  IF NEW."id" <> OLD."id" OR NEW."scanPlanId" <> OLD."scanPlanId" OR NEW."userId" <> OLD."userId"
     OR NEW."targetId" <> OLD."targetId" OR NEW."executionUnitClass" <> OLD."executionUnitClass"
     OR NEW."idempotencyKey" <> OLD."idempotencyKey" OR NEW."configuration"::text <> OLD."configuration"::text
     OR NEW."requiresSafetyCheckpoint" <> OLD."requiresSafetyCheckpoint" THEN
    RAISE EXCEPTION 'execution_unit_immutable_column' USING ERRCODE = '23514';
  END IF;
  IF OLD."status" IN ('SKIPPED','BLOCKED','REFUSED','COMPLETED','FAILED','CANCELLED','KILLED') THEN
    RAISE EXCEPTION 'execution_unit_terminal:%', OLD."status" USING ERRCODE = '23514';
  END IF;
  IF NEW."status" <> OLD."status" AND NOT (
       (OLD."status" = 'PLANNED'    AND NEW."status" IN ('ADMITTED','BLOCKED','REFUSED','COMPLETED'))
    OR (OLD."status" = 'ADMITTED'   AND NEW."status" IN ('DISPATCHED','REFUSED'))
    OR (OLD."status" = 'DISPATCHED' AND NEW."status" IN ('RUNNING','REFUSED'))
    OR (OLD."status" = 'RUNNING'    AND NEW."status" IN ('COMPLETED','FAILED','CANCELLED','KILLED'))) THEN
    RAISE EXCEPTION 'execution_unit_invalid_transition:%->%', OLD."status", NEW."status" USING ERRCODE = '23514';
  END IF;
  -- TELEMETRY is the only class that completes straight from PLANNED.
  IF OLD."status" = 'PLANNED' AND NEW."status" = 'COMPLETED' AND OLD."executionUnitClass" <> 'TELEMETRY' THEN
    RAISE EXCEPTION 'execution_unit_invalid_transition:PLANNED->COMPLETED' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER "ExecutionUnit_guard" BEFORE UPDATE ON "ExecutionUnit" FOR EACH ROW EXECUTE FUNCTION public.fahes_unit_guard();

-- Rows that must never be updated: the plan (immutable snapshot, FR-006/015), edges, claims.
CREATE FUNCTION public.fahes_immutable_row() RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN RAISE EXCEPTION 'immutable_row:%', TG_TABLE_NAME USING ERRCODE = '23514'; END $$;
CREATE TRIGGER "ScanPlan_immutable" BEFORE UPDATE ON "ScanPlan" FOR EACH ROW EXECUTE FUNCTION public.fahes_immutable_row();
CREATE TRIGGER "ExecutionDependency_immutable" BEFORE UPDATE ON "ExecutionDependency" FOR EACH ROW EXECUTE FUNCTION public.fahes_immutable_row();
CREATE TRIGGER "ExecutionUnitHostClaim_immutable" BEFORE UPDATE ON "ExecutionUnitHostClaim" FOR EACH ROW EXECUTE FUNCTION public.fahes_immutable_row();

-- FR-013: an edge joins two units of the same plan.
CREATE FUNCTION public.fahes_dependency_same_plan() RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $$
DECLARE a text; b text;
BEGIN
  SELECT "scanPlanId" INTO a FROM "ExecutionUnit" WHERE id = NEW."executionUnitId";
  SELECT "scanPlanId" INTO b FROM "ExecutionUnit" WHERE id = NEW."dependsOnExecutionUnitId";
  IF a IS NULL OR b IS NULL OR a <> b THEN RAISE EXCEPTION 'dependency_cross_plan' USING ERRCODE = '23514'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER "ExecutionDependency_same_plan" BEFORE INSERT ON "ExecutionDependency" FOR EACH ROW EXECUTE FUNCTION public.fahes_dependency_same_plan();

-- Effect ledger lifecycle: AUTHORIZED -> CONFIRMED | ABANDONED only.
CREATE FUNCTION public.fahes_effect_guard() RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  IF OLD."state" <> 'AUTHORIZED' OR NEW."state" = 'AUTHORIZED'
     OR NEW."executionUnitId" <> OLD."executionUnitId" OR NEW."attempt" <> OLD."attempt"
     OR NEW."kind" <> OLD."kind" OR NEW."ordinal" <> OLD."ordinal" THEN
    RAISE EXCEPTION 'effect_authorization_invalid_transition' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER "EffectAuthorization_guard" BEFORE UPDATE ON "EffectAuthorization" FOR EACH ROW EXECUTE FUNCTION public.fahes_effect_guard();

-- ---------------------------------------------------------------------------
-- fahes_finalize_unit — the ONE finalization body (DEC-047 option A).
-- Unit row first, then (inside f07_release_leases_by_execution) the 008 lock order.
-- Returns {status, replayed, outcomeMatches, blocked: [unit ids]}.
-- ---------------------------------------------------------------------------
CREATE FUNCTION public.fahes_finalize_unit(
  p_unit_id text, p_idempotency_key text, p_kind text,
  p_failure_class "FailureClass" DEFAULT NULL, p_reason text DEFAULT NULL, p_progress jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp SET lock_timeout = '5s' AS $$
DECLARE
  u "ExecutionUnit"%ROWTYPE; v_to "ExecutionUnitStatus"; v_now timestamptz := clock_timestamp();
  v_blocked text[] := ARRAY[]::text[]; v_queue text[]; v_cur text; d record;
BEGIN
  IF p_kind NOT IN ('COMPLETED','FAILED','CANCELLED','KILLED','REFUSED') THEN
    RAISE EXCEPTION 'finalize_invalid_kind' USING ERRCODE = '22023';
  END IF;
  IF (p_kind = 'FAILED') <> (p_failure_class IS NOT NULL) OR p_failure_class = 'DETERMINISTIC_FINDING' THEN
    RAISE EXCEPTION 'finalize_invalid_failure_class' USING ERRCODE = '22023';
  END IF;
  v_to := p_kind::"ExecutionUnitStatus";
  SELECT * INTO u FROM "ExecutionUnit" WHERE id = p_unit_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'finalize_unit_not_found' USING ERRCODE = 'P0002'; END IF;
  IF u."idempotencyKey" <> p_idempotency_key THEN RAISE EXCEPTION 'finalize_stale_idempotency_key' USING ERRCODE = '23514'; END IF;

  IF u."status" IN ('SKIPPED','BLOCKED','REFUSED','COMPLETED','FAILED','CANCELLED','KILLED') THEN
    RETURN jsonb_build_object('status', u."status", 'replayed', true, 'outcomeMatches', u."status" = v_to, 'blocked', '[]'::jsonb);
  END IF;
  IF NOT ((p_kind = 'REFUSED' AND u."status" IN ('PLANNED','ADMITTED','DISPATCHED'))
       OR (p_kind IN ('COMPLETED','FAILED','CANCELLED','KILLED') AND u."status" = 'RUNNING')
       OR (p_kind = 'COMPLETED' AND u."status" = 'PLANNED' AND u."executionUnitClass" = 'TELEMETRY')) THEN
    RAISE EXCEPTION 'finalize_invalid_transition:%->%', u."status", v_to USING ERRCODE = '23514';
  END IF;

  PERFORM public.f07_release_leases_by_execution(p_unit_id);       -- step 2, same transaction
  PERFORM public.f07_ack_stop_by_authority(p_unit_id);             -- v6 section 7 (DEC-048 A)
  UPDATE "EffectAuthorization" SET "state" = 'ABANDONED' WHERE "executionUnitId" = p_unit_id AND "state" = 'AUTHORIZED';

  UPDATE "ExecutionUnit" SET "status" = v_to, "failureClass" = p_failure_class, "terminalReason" = p_reason,
         "completedAt" = v_now, "progressSnapshot" = coalesce(p_progress, "progressSnapshot")
   WHERE id = p_unit_id;

  IF p_kind <> 'COMPLETED' THEN                                    -- step 5, repeated application, same transaction
    v_queue := ARRAY[p_unit_id];
    WHILE coalesce(array_length(v_queue, 1), 0) > 0 LOOP
      v_cur := v_queue[1]; v_queue := v_queue[2:array_length(v_queue, 1)];
      FOR d IN SELECT x.id FROM "ExecutionDependency" e JOIN "ExecutionUnit" x ON x.id = e."executionUnitId"
               WHERE e."dependsOnExecutionUnitId" = v_cur
                 AND x."status" NOT IN ('SKIPPED','BLOCKED','REFUSED','COMPLETED','FAILED','CANCELLED','KILLED')
               ORDER BY x.id FOR UPDATE OF x LOOP
        UPDATE "ExecutionUnit" SET "status" = 'BLOCKED', "blockedByExecutionUnitId" = v_cur, "completedAt" = v_now WHERE id = d.id;
        v_blocked := v_blocked || d.id; v_queue := v_queue || d.id;
      END LOOP;
    END LOOP;
  END IF;
  RETURN jsonb_build_object('status', v_to, 'replayed', false, 'outcomeMatches', true, 'blocked', to_jsonb(v_blocked));
END $$;
REVOKE ALL ON FUNCTION public.fahes_finalize_unit(text,text,text,"FailureClass",text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fahes_finalize_unit(text,text,text,"FailureClass",text,jsonb) TO fahes_api, fahes_worker_exec, fahes_orchestrator;
